head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


(function() {
    $('.familySiteWrap').on('mouseover', function() {
        $('.familySiteList').stop(true).show().parent().css({
            background: '#1b1b1b url("/img/footer/arrowUp.png") no-repeat 150px center'
        });
    }).on('mouseout', function() {
        $('.familySiteList').stop(true).hide().parent().css({
            background: '#1b1b1b url("/img/footer/arrowDown.png") no-repeat 150px center'
        });
    });
}());
